// ============================================================
// Hero Carousel
// ============================================================
(function() {
  let current = 0;
  const total = 5;
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.hero-dot');
  let autoplay;

  function goTo(index) {
    slides.forEach(s => s.classList.remove('active'));
    dots.forEach(d => d.classList.remove('active'));
    current = (index + total) % total;
    slides[current].classList.add('active');
    dots[current].classList.add('active');
  }

  function next() { goTo(current + 1); }
  function prev() { goTo(current - 1); }

  document.getElementById('heroNext').addEventListener('click', () => { next(); resetAutoplay(); });
  document.getElementById('heroPrev').addEventListener('click', () => { prev(); resetAutoplay(); });
  dots.forEach(d => { d.addEventListener('click', () => { goTo(parseInt(d.dataset.index)); resetAutoplay(); }); });

  function resetAutoplay() { clearInterval(autoplay); startAutoplay(); }
  function startAutoplay() { autoplay = setInterval(next, 6000); }

  // Touch swipe support
  let touchX = 0;
  const heroEl = document.getElementById('heroCarousel');
  heroEl.addEventListener('touchstart', e => { touchX = e.touches[0].clientX; });
  heroEl.addEventListener('touchend', e => {
    const diff = touchX - e.changedTouches[0].clientX;
    if (Math.abs(diff) > 50) { diff > 0 ? next() : prev(); resetAutoplay(); }
  });

  // Keyboard navigation
  heroEl.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft') { prev(); resetAutoplay(); }
    if (e.key === 'ArrowRight') { next(); resetAutoplay(); }
  });

  startAutoplay();
})();

